import { useState } from "react";
import type { Comment } from "@/types";
import { ThumbsUp, BadgeCheck, Send } from "lucide-react";
import { cn } from "@/lib/utils";

// 评论区：模拟社区讨论 + 三层共建模型标识（官方认证用户）
export default function Comments({ comments }: { comments: Comment[] }) {
  const [liked, setLiked] = useState<Record<string, boolean>>({});

  const toggleLike = (id: string) => {
    setLiked((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  return (
    <div className="mt-12">
      <div className="flex items-center gap-2 mb-5">
        <h3 className="font-display text-2xl tracking-wide text-white">
          社区讨论
        </h3>
        <span className="text-xs text-text-muted ml-auto">
          {comments.length} 条 · 文明交流
        </span>
      </div>

      {/* 评论输入框（模拟） */}
      <div className="glass-card p-4 mb-5">
        <div className="flex items-start gap-3">
          <div className="w-9 h-9 rounded-full bg-gradient-to-br from-accent-pink to-accent-purple flex items-center justify-center text-sm font-bold text-white flex-shrink-0">
            我
          </div>
          <div className="flex-1">
            <textarea
              placeholder="分享你对这首歌的理解，或补充一个知识点……"
              className="w-full bg-transparent border-none outline-none resize-none text-sm text-white placeholder:text-text-muted min-h-[44px]"
              rows={2}
            />
            <div className="flex justify-end mt-2">
              <button className="inline-flex items-center gap-1.5 px-4 py-1.5 rounded-full bg-accent-pink/20 text-accent-pink text-xs font-semibold hover:bg-accent-pink hover:text-white transition-all">
                <Send className="w-3 h-3" />
                发布
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* 评论列表 */}
      <div className="space-y-3">
        {comments.map((c) => {
          const isLiked = liked[c.id];
          return (
            <div key={c.id} className="glass-card p-4">
              <div className="flex items-start gap-3">
                <div className="w-9 h-9 rounded-full bg-bg-hover flex items-center justify-center text-base flex-shrink-0">
                  {c.avatar}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-sm font-medium text-white">
                      {c.user}
                    </span>
                    {c.verified && (
                      <span className="inline-flex items-center gap-1 badge bg-accent-pink/15 text-accent-pink border border-accent-pink/30">
                        <BadgeCheck className="w-3 h-3" />
                        官方认证
                      </span>
                    )}
                    <span className="text-xs text-text-muted ml-auto">
                      {c.time}
                    </span>
                  </div>
                  <p className="text-sm text-text-secondary leading-relaxed mb-2">
                    {c.content}
                  </p>
                  <button
                    onClick={() => toggleLike(c.id)}
                    className={cn(
                      "inline-flex items-center gap-1.5 text-xs transition-colors",
                      isLiked
                        ? "text-accent-pink"
                        : "text-text-muted hover:text-accent-pink"
                    )}
                  >
                    <ThumbsUp
                      className={cn("w-3.5 h-3.5", isLiked && "fill-accent-pink")}
                    />
                    {c.likes + (isLiked ? 1 : 0)}
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
