import { Link, useLocation } from "react-router-dom";
import { Languages, Music2 } from "lucide-react";
import { useStore } from "@/store";
import { cn } from "@/lib/utils";

export default function Header() {
  const { langMode, toggleLangMode } = useStore();
  const location = useLocation();
  const isDetail = location.pathname.startsWith("/song/");

  return (
    <header className="sticky top-0 z-50 backdrop-blur-xl bg-bg-primary/70 border-b border-white/[0.06]">
      <div className="container flex items-center justify-between h-16">
        {/* Logo */}
        <Link to="/" className="group flex items-center gap-2.5">
          <div className="relative">
            <div className="w-9 h-9 rounded-xl bg-gradient-to-br from-accent-pink to-accent-purple flex items-center justify-center shadow-[0_0_20px_rgba(255,61,139,0.4)] group-hover:shadow-[0_0_30px_rgba(255,61,139,0.6)] transition-all">
              <Music2 className="w-5 h-5 text-white" strokeWidth={2.5} />
            </div>
          </div>
          <div className="flex flex-col leading-none">
            <span className="font-display text-xl tracking-wider text-white">
              译声
            </span>
            <span className="text-[10px] font-mono tracking-[0.2em] text-text-muted uppercase">
              LyriDecoded
            </span>
          </div>
        </Link>

        {/* 中间导航 */}
        <nav className="hidden md:flex items-center gap-1">
          <NavLink to="/" label="发现" active={location.pathname === "/"} />
          <NavLink to="/" label="分类" />
          <NavLink to="/" label="学习" />
          <NavLink to="/" label="社区" />
        </nav>

        {/* 右侧：中/EN 开关 */}
        <div className="flex items-center gap-3">
          {isDetail && (
            <Link
              to="/"
              className="hidden sm:inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-sm text-text-secondary hover:text-white hover:bg-white/5 transition-colors"
            >
              ← 返回
            </Link>
          )}
          <button
            onClick={toggleLangMode}
            className="relative flex items-center gap-1.5 px-3 py-1.5 rounded-full border border-white/10 bg-white/5 hover:bg-white/10 hover:border-accent-pink/40 transition-all group"
            title="切换中英优先模式"
          >
            <Languages className="w-4 h-4 text-accent-cyan" />
            <span
              className={cn(
                "text-xs font-mono font-semibold transition-colors",
                langMode === "en" ? "text-accent-cyan" : "text-text-muted"
              )}
            >
              EN
            </span>
            <span className="text-xs text-text-muted">/</span>
            <span
              className={cn(
                "text-xs font-mono font-semibold transition-colors",
                langMode === "cn" ? "text-accent-pink" : "text-text-muted"
              )}
            >
              中
            </span>
            <span className="hidden sm:inline text-[10px] text-text-muted ml-0.5">
              {langMode === "en" ? "默认英文" : "默认中文"}
            </span>
          </button>
        </div>
      </div>
    </header>
  );
}

function NavLink({
  to,
  label,
  active,
}: {
  to: string;
  label: string;
  active?: boolean;
}) {
  return (
    <Link
      to={to}
      className={cn(
        "px-3 py-1.5 rounded-full text-sm transition-colors",
        active
          ? "text-white bg-white/10"
          : "text-text-secondary hover:text-white hover:bg-white/5"
      )}
    >
      {label}
    </Link>
  );
}
