import type { KnowledgePoint, Level } from "@/types";
import { useStore } from "@/store";
import { cn } from "@/lib/utils";
import { GraduationCap, BookOpen, MessageCircle, PenLine } from "lucide-react";

// 知识点 Tab：B1/B2/C1 难度分级切换 + 考点列表
export default function KnowledgeTab({
  points,
}: {
  points: KnowledgePoint[];
}) {
  const { knowledgeLevel, setKnowledgeLevel } = useStore();

  const levels: { value: Level | "all"; label: string; desc: string }[] = [
    { value: "all", label: "全部", desc: "显示所有难度" },
    { value: "B1", label: "B1", desc: "中级 · 基础词汇与句型" },
    { value: "B2", label: "B2", desc: "中高级 · 表达与语法点" },
    { value: "C1", label: "C1", desc: "高级 · 修辞与文化概念" },
  ];

  const filtered =
    knowledgeLevel === "all"
      ? points
      : points.filter((p) => p.level === knowledgeLevel);

  const typeIcons = {
    vocab: <BookOpen className="w-3.5 h-3.5" />,
    grammar: <PenLine className="w-3.5 h-3.5" />,
    expression: <MessageCircle className="w-3.5 h-3.5" />,
  };

  const typeLabels = {
    vocab: "词汇",
    grammar: "语法",
    expression: "表达",
  };

  const levelColors: Record<Level, string> = {
    B1: "bg-green-500/15 text-green-400 border-green-500/30",
    B2: "bg-yellow-500/15 text-yellow-400 border-yellow-500/30",
    C1: "bg-red-500/15 text-red-400 border-red-500/30",
  };

  return (
    <div className="animate-fade-in">
      <div className="flex items-center gap-2 mb-5">
        <GraduationCap className="w-5 h-5 text-accent-purple" />
        <h3 className="font-display text-2xl tracking-wide text-white">
          英语知识点（CEFR 分级）
        </h3>
      </div>

      {/* 难度分级切换 */}
      <div className="flex flex-wrap gap-2 mb-6">
        {levels.map((lvl) => (
          <button
            key={lvl.value}
            onClick={() => setKnowledgeLevel(lvl.value)}
            className={cn(
              "group relative px-4 py-2 rounded-full text-sm font-mono font-semibold transition-all border",
              knowledgeLevel === lvl.value
                ? "bg-accent-pink text-white border-accent-pink shadow-[0_0_20px_rgba(255,61,139,0.3)]"
                : "bg-white/5 text-text-secondary border-white/10 hover:border-white/20 hover:text-white"
            )}
            title={lvl.desc}
          >
            {lvl.label}
          </button>
        ))}
      </div>

      {/* 当前分级说明 */}
      <div className="mb-5 text-xs text-text-muted">
        {levels.find((l) => l.value === knowledgeLevel)?.desc} · 共{" "}
        {filtered.length} 条
      </div>

      {/* 知识点列表 */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
        {filtered.map((p) => (
          <div
            key={p.id}
            className="glass-card p-4 hover:border-accent-purple/30 transition-colors"
          >
            <div className="flex items-center justify-between mb-2">
              <h4 className="font-display text-lg tracking-wide text-white">
                {p.term}
              </h4>
              <div className="flex items-center gap-1.5">
                <span
                  className={cn(
                    "badge border font-mono",
                    levelColors[p.level]
                  )}
                >
                  {p.level}
                </span>
                <span className="inline-flex items-center gap-1 badge bg-accent-purple/10 text-accent-purple border border-accent-purple/20">
                  {typeIcons[p.type]}
                  {typeLabels[p.type]}
                </span>
              </div>
            </div>
            <p className="text-sm text-text-primary leading-relaxed mb-1.5">
              {p.en}
            </p>
            <p className="text-xs text-text-secondary leading-relaxed mb-2">
              {p.cn}
            </p>
            {p.example && (
              <p className="text-xs font-lyric italic text-accent-cyan/90 border-l-2 border-accent-cyan/30 pl-2">
                {p.example}
              </p>
            )}
          </div>
        ))}
      </div>

      {filtered.length === 0 && (
        <div className="text-center py-12 text-text-muted text-sm">
          该难度暂无知识点
        </div>
      )}
    </div>
  );
}
