import { useState } from "react";
import { useParams, Link } from "react-router-dom";
import { ArrowLeft, Calendar, Disc3, BarChart3, ExternalLink } from "lucide-react";
import { antiHeroSong } from "@/data/songs";
import LyricsTab from "@/components/song/LyricsTab";
import AllusionsTab from "@/components/song/AllusionsTab";
import SlangTab from "@/components/song/SlangTab";
import KnowledgeTab from "@/components/song/KnowledgeTab";
import Comments from "@/components/song/Comments";
import { cn } from "@/lib/utils";

type TabKey = "lyrics" | "allusions" | "slang" | "knowledge";

const tabs: { key: TabKey; label: string; labelEn: string }[] = [
  { key: "lyrics", label: "歌词解读", labelEn: "Lyrics" },
  { key: "allusions", label: "典故", labelEn: "Allusions" },
  { key: "slang", label: "俚语", labelEn: "Slang" },
  { key: "knowledge", label: "知识点", labelEn: "Knowledge" },
];

export default function SongDetail() {
  const { songId } = useParams();
  const [activeTab, setActiveTab] = useState<TabKey>("lyrics");

  // Demo 内仅有 Anti-Hero
  const song = antiHeroSong;

  if (songId !== song.id) {
    return (
      <div className="container py-20 text-center">
        <p className="text-text-secondary mb-4">Demo 暂未收录此歌曲</p>
        <Link to="/" className="btn-primary">
          返回首页
        </Link>
      </div>
    );
  }

  return (
    <div className="animate-fade-in">
      {/* 歌曲信息区 */}
      <section className="relative overflow-hidden">
        {/* 背景氛围 */}
        <div
          className="absolute inset-0 opacity-40"
          style={{ background: song.coverGradient }}
        />
        <div className="absolute inset-0 bg-gradient-to-b from-bg-primary/30 via-bg-primary/70 to-bg-primary" />
        <div className="absolute inset-0 bg-noise opacity-20 mix-blend-overlay" />

        <div className="container relative pt-8 pb-10">
          {/* 返回 */}
          <Link
            to="/"
            className="inline-flex items-center gap-1.5 text-sm text-text-secondary hover:text-white transition-colors mb-6"
          >
            <ArrowLeft className="w-4 h-4" />
            返回首页
          </Link>

          <div className="flex flex-col md:flex-row gap-6 md:gap-8">
            {/* 封面 */}
            <div
              className="w-40 h-40 md:w-52 md:h-52 rounded-2xl flex-shrink-0 relative overflow-hidden shadow-2xl"
              style={{ background: song.coverGradient }}
            >
              <div className="absolute inset-0 bg-noise opacity-30 mix-blend-overlay" />
              <div className="absolute bottom-3 left-3 right-3">
                <div className="text-white/90 font-display text-2xl tracking-wider drop-shadow-lg">
                  {song.title}
                </div>
              </div>
              {/* 装饰音波 */}
              <div className="absolute top-3 right-3 flex items-end gap-0.5 h-4 opacity-60">
                {[0.5, 0.8, 0.4, 1, 0.6].map((h, i) => (
                  <div
                    key={i}
                    className="w-0.5 bg-white rounded-full"
                    style={{ height: `${h * 100}%` }}
                  />
                ))}
              </div>
            </div>

            {/* 信息 */}
            <div className="flex-1 min-w-0">
              <div className="section-eyebrow">SONG · 歌曲解读</div>
              <h1 className="font-display text-4xl md:text-6xl tracking-wider text-white mb-1 leading-none">
                {song.title}
              </h1>
              <p className="text-lg text-accent-pink/90 mb-3">{song.titleCn}</p>

              <div className="flex flex-wrap items-center gap-x-4 gap-y-2 text-sm text-text-secondary mb-4">
                <span className="font-medium text-white">{song.artist}</span>
                <span className="inline-flex items-center gap-1">
                  <Disc3 className="w-3.5 h-3.5" />
                  {song.album}
                </span>
                <span className="inline-flex items-center gap-1">
                  <Calendar className="w-3.5 h-3.5" />
                  {song.year}
                </span>
                <span className="inline-flex items-center gap-1">
                  <BarChart3 className="w-3.5 h-3.5" />
                  难度
                  <span className="inline-flex px-1.5 py-0.5 rounded text-[10px] font-mono font-semibold bg-yellow-500/15 text-yellow-400 border border-yellow-500/30">
                    {song.difficulty}
                  </span>
                </span>
              </div>

              <p className="text-sm md:text-base text-text-secondary leading-relaxed max-w-2xl mb-4">
                {song.intro}
              </p>

              {/* 参考资料链接（合规） */}
              <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-text-muted">
                <span className="font-mono">参考资料：</span>
                {song.references.map((ref) => (
                  <a
                    key={ref.url}
                    href={ref.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 hover:text-accent-cyan transition-colors"
                  >
                    {ref.label}
                    <ExternalLink className="w-3 h-3" />
                  </a>
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Tab 导航 */}
      <section className="sticky top-16 z-40 backdrop-blur-xl bg-bg-primary/80 border-y border-white/[0.06]">
        <div className="container">
          <div className="flex items-center gap-1 overflow-x-auto py-2">
            {tabs.map((tab) => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={cn(
                  "relative flex-shrink-0 px-4 py-2 rounded-full text-sm font-medium transition-all",
                  activeTab === tab.key
                    ? "text-white bg-white/10"
                    : "text-text-muted hover:text-white hover:bg-white/5"
                )}
              >
                <span className="relative z-10">{tab.label}</span>
                <span className="ml-1.5 text-[10px] font-mono opacity-60">
                  {tab.labelEn}
                </span>
                {activeTab === tab.key && (
                  <span className="absolute bottom-0 left-1/2 -translate-x-1/2 w-8 h-0.5 bg-accent-pink rounded-full" />
                )}
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Tab 内容 */}
      <section className="container py-8 md:py-10">
        {activeTab === "lyrics" && <LyricsTab lyrics={song.lyrics} />}
        {activeTab === "allusions" && (
          <AllusionsTab allusions={song.allusions} />
        )}
        {activeTab === "slang" && <SlangTab slang={song.slang} />}
        {activeTab === "knowledge" && (
          <KnowledgeTab points={song.knowledgePoints} />
        )}

        {/* 评论区（始终展示在 Tab 内容下方） */}
        <Comments comments={song.comments} />
      </section>
    </div>
  );
}
