import { useState, useEffect } from "react";
import { ChevronDown, Languages } from "lucide-react";
import { useStore } from "@/store";
import { cn as cx } from "@/lib/utils";

// 通用翻译卡片：英文优先，可单独切换中文，也响应全局中英开关
export default function TranslationCard({
  titleEn,
  titleCn,
  en,
  cn,
  tags,
  extra,
}: {
  titleEn?: string;
  titleCn?: string;
  en: string;
  cn: string;
  tags?: string[];
  extra?: React.ReactNode;
}) {
  const { langMode } = useStore();
  // 全局 cn 模式下默认展开；全局 en 模式下默认收起
  const [expanded, setExpanded] = useState(langMode === "cn");

  // 全局语言切换时同步
  useEffect(() => {
    setExpanded(langMode === "cn");
  }, [langMode]);

  return (
    <div className="glass-card p-5 md:p-6 group">
      {/* 标题 */}
      {(titleEn || titleCn) && (
        <div className="mb-3">
          {titleEn && (
            <h3 className="font-display text-xl md:text-2xl tracking-wide text-white mb-0.5">
              {titleEn}
            </h3>
          )}
          {titleCn && (
            <p className="text-xs text-accent-pink/80 font-medium">{titleCn}</p>
          )}
        </div>
      )}

      {/* 标签 */}
      {tags && tags.length > 0 && (
        <div className="flex flex-wrap gap-1.5 mb-3">
          {tags.map((tag) => (
            <span
              key={tag}
              className="badge bg-accent-cyan/10 text-accent-cyan border border-accent-cyan/20"
            >
              {tag}
            </span>
          ))}
        </div>
      )}

      {/* 英文原文（始终展示） */}
      <p className="font-lyric text-base md:text-lg text-text-primary leading-relaxed mb-3">
        {en}
      </p>

      {/* 中文翻译（可折叠） */}
      <div
        className={cx(
          "grid transition-all duration-300",
          expanded
            ? "grid-rows-[1fr] opacity-100"
            : "grid-rows-[0fr] opacity-0"
        )}
      >
        <div className="overflow-hidden">
          <div className="pt-3 border-t border-white/[0.06]">
            <div className="flex items-start gap-2">
              <Languages className="w-4 h-4 text-accent-pink flex-shrink-0 mt-0.5" />
              <p className="text-sm text-text-secondary leading-relaxed">
                {cn}
              </p>
            </div>
            {extra}
          </div>
        </div>
      </div>

      {/* 切换按钮 */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="mt-3 inline-flex items-center gap-1.5 text-xs font-mono text-text-muted hover:text-accent-pink transition-colors"
      >
        <ChevronDown
          className={cx(
            "w-3.5 h-3.5 transition-transform",
            expanded && "rotate-180"
          )}
        />
        {expanded ? "Hide Chinese" : "View Chinese"}
      </button>
    </div>
  );
}
