import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Search, Sparkles, ArrowRight, Lock, Headphones, GraduationCap, Users } from "lucide-react";
import { homeSongs } from "@/data/songs";

export default function Home() {
  const [query, setQuery] = useState("");
  const navigate = useNavigate();

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    // 前端模拟：输入 anti-hero 或 taylor 直达
    const q = query.trim().toLowerCase();
    if (q.includes("anti") || q.includes("taylor") || q.includes("hero")) {
      navigate("/song/anti-hero");
    } else if (q) {
      navigate("/song/anti-hero"); // demo 内只有一首，统一跳转
    }
  };

  return (
    <div className="animate-fade-in">
      {/* Hero 区 */}
      <section className="relative overflow-hidden">
        {/* 背景氛围层 */}
        <div className="absolute inset-0 pointer-events-none">
          <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[800px] h-[500px] bg-accent-pink/15 rounded-full blur-[120px]" />
          <div className="absolute top-40 right-10 w-[400px] h-[400px] bg-accent-purple/10 rounded-full blur-[100px]" />
          <div className="absolute top-20 left-10 w-[300px] h-[300px] bg-accent-cyan/8 rounded-full blur-[90px]" />
        </div>

        <div className="container relative pt-20 pb-16 md:pt-28 md:pb-24">
          <div className="max-w-4xl mx-auto text-center">
            <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full bg-white/5 border border-white/10 backdrop-blur-sm mb-8 animate-fade-up">
              <Sparkles className="w-3.5 h-3.5 text-accent-pink" />
              <span className="text-xs font-mono tracking-wider text-text-secondary">
                TRAE 创意赛 · 学习工作赛道
              </span>
            </div>

            <h1
              className="font-display text-6xl md:text-8xl lg:text-9xl tracking-wider leading-[0.9] mb-4 animate-fade-up"
              style={{ animationDelay: "0.1s", opacity: 0 }}
            >
              <span className="block text-white">译声</span>
              <span className="block gradient-text text-glow-pink">
                LyriDecoded
              </span>
            </h1>

            <p
              className="text-xl md:text-2xl text-text-secondary font-light mb-2 animate-fade-up"
              style={{ animationDelay: "0.2s", opacity: 0 }}
            >
              听懂歌，读懂词，<span className="text-white font-medium">顺便把英语学了</span>
            </p>
            <p
              className="text-sm md:text-base text-text-muted max-w-2xl mx-auto mb-10 animate-fade-up"
              style={{ animationDelay: "0.3s", opacity: 0 }}
            >
              专为中文母语者打造的歌曲解读与英语学习平台 ——
              不是机翻歌词，而是典故、俚语、文化背景的深度解码。
            </p>

            {/* 搜索框 */}
            <form
              onSubmit={handleSearch}
              className="max-w-xl mx-auto animate-fade-up"
              style={{ animationDelay: "0.4s", opacity: 0 }}
            >
              <div className="relative group">
                <div className="absolute inset-0 bg-gradient-to-r from-accent-pink via-accent-purple to-accent-cyan rounded-full blur opacity-40 group-focus-within:opacity-70 transition-opacity" />
                <div className="relative flex items-center bg-bg-secondary/90 backdrop-blur-xl rounded-full border border-white/10 pl-5 pr-2 py-2">
                  <Search className="w-5 h-5 text-text-muted flex-shrink-0" />
                  <input
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    placeholder="搜索歌曲 / 歌手，试试 'Anti-Hero'"
                    className="flex-1 bg-transparent border-none outline-none px-3 py-1.5 text-sm md:text-base text-white placeholder:text-text-muted"
                  />
                  <button
                    type="submit"
                    className="flex-shrink-0 px-5 py-2 rounded-full bg-accent-pink hover:bg-accent-pink/90 text-white text-sm font-semibold transition-all hover:shadow-[0_0_20px_rgba(255,61,139,0.5)]"
                  >
                    搜索
                  </button>
                </div>
              </div>
            </form>
          </div>
        </div>
      </section>

      {/* 热门歌曲区 */}
      <section className="container py-12 md:py-16">
        <div className="flex items-end justify-between mb-8">
          <div>
            <div className="section-eyebrow">FEATURED · 精选解读</div>
            <h2 className="font-display text-3xl md:text-4xl tracking-wider text-white">
              从这首歌开始解码
            </h2>
          </div>
          <div className="hidden md:flex items-center gap-1 text-xs text-text-muted">
            <Lock className="w-3 h-3" />
            <span>灰色卡片为 Demo 待解锁</span>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
          {homeSongs.map((song, idx) =>
            song.available ? (
              <Link
                key={song.id}
                to={`/song/${song.id}`}
                className="group glass-card overflow-hidden animate-fade-up"
                style={{ animationDelay: `${0.5 + idx * 0.08}s`, opacity: 0 }}
              >
                <SongCard song={song} />
                <div className="px-5 py-4">
                  <div className="flex items-center justify-between mb-1">
                    <h3 className="font-display text-xl tracking-wide text-white group-hover:text-accent-pink transition-colors">
                      {song.title}
                    </h3>
                    <ArrowRight className="w-4 h-4 text-text-muted group-hover:text-accent-pink group-hover:translate-x-1 transition-all" />
                  </div>
                  <p className="text-xs text-text-muted mb-2">
                    {song.artist} · {song.difficulty}
                  </p>
                  <p className="text-xs text-text-secondary leading-relaxed line-clamp-2">
                    {song.shortDesc}
                  </p>
                </div>
              </Link>
            ) : (
              <div
                key={song.id}
                className="glass-card overflow-hidden opacity-60 animate-fade-up"
                style={{ animationDelay: `${0.5 + idx * 0.08}s`, opacity: 0 }}
              >
                <SongCard song={song} />
                <div className="px-5 py-4">
                  <div className="flex items-center justify-between mb-1">
                    <h3 className="font-display text-xl tracking-wide text-text-secondary">
                      {song.title}
                    </h3>
                    <Lock className="w-4 h-4 text-text-muted" />
                  </div>
                  <p className="text-xs text-text-muted mb-2">
                    {song.artist} · {song.difficulty}
                  </p>
                  <p className="text-xs text-text-muted leading-relaxed line-clamp-2">
                    {song.shortDesc}
                  </p>
                </div>
              </div>
            )
          )}
        </div>
      </section>

      {/* 三大特色 */}
      <section className="container py-12 md:py-16">
        <div className="text-center mb-10">
          <div className="section-eyebrow">WHY 译声</div>
          <h2 className="font-display text-3xl md:text-4xl tracking-wider text-white">
            不只是翻译，更是桥梁
          </h2>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
          <FeatureCard
            icon={<Headphones className="w-6 h-6" />}
            title="深度解读"
            desc="典故、文化背景、创作脉络——把歌词里埋的故事挖出来，而不是停在字面。"
            color="pink"
            delay={0.7}
          />
          <FeatureCard
            icon={<GraduationCap className="w-6 h-6" />}
            title="分级学习"
            desc="B1/B2/C1 难度标注，考点高亮，把流行歌变成可量化的英语输入材料。"
            color="cyan"
            delay={0.78}
          />
          <FeatureCard
            icon={<Users className="w-6 h-6" />}
            title="共建社区"
            desc="官方保底线、用户补长尾、高赞被采纳——让多元视角沉淀而非散落。"
            color="purple"
            delay={0.86}
          />
        </div>
      </section>
    </div>
  );
}

function SongCard({ song }: { song: { coverGradient: string; title: string } }) {
  return (
    <div
      className="aspect-square relative overflow-hidden"
      style={{ background: song.coverGradient }}
    >
      <div className="absolute inset-0 bg-noise opacity-30 mix-blend-overlay" />
      <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />
      {/* 装饰性音波 */}
      <div className="absolute bottom-4 left-4 flex items-end gap-0.5 h-6 opacity-70">
        {[0.4, 0.7, 1, 0.5, 0.8, 0.3, 0.6].map((h, i) => (
          <div
            key={i}
            className="w-0.5 bg-white/80 rounded-full"
            style={{ height: `${h * 100}%` }}
          />
        ))}
      </div>
      <div className="absolute top-4 right-4 text-white/90 font-display text-3xl tracking-wider drop-shadow-lg">
        {song.title}
      </div>
    </div>
  );
}

function FeatureCard({
  icon,
  title,
  desc,
  color,
  delay,
}: {
  icon: React.ReactNode;
  title: string;
  desc: string;
  color: "pink" | "cyan" | "purple";
  delay: number;
}) {
  const colorMap = {
    pink: "text-accent-pink bg-accent-pink/10 border-accent-pink/20",
    cyan: "text-accent-cyan bg-accent-cyan/10 border-accent-cyan/20",
    purple: "text-accent-purple bg-accent-purple/10 border-accent-purple/20",
  };
  return (
    <div
      className="glass-card p-6 animate-fade-up"
      style={{ animationDelay: `${delay}s`, opacity: 0 }}
    >
      <div
        className={`inline-flex items-center justify-center w-12 h-12 rounded-xl border mb-4 ${colorMap[color]}`}
      >
        {icon}
      </div>
      <h3 className="font-display text-2xl tracking-wide text-white mb-2">
        {title}
      </h3>
      <p className="text-sm text-text-secondary leading-relaxed">{desc}</p>
    </div>
  );
}
