import { create } from "zustand";
import type { Level } from "@/types";

// 译声 Demo 全局状态

interface AppState {
  // 全局语言模式：'en' 英文优先（默认）/ 'cn' 中文优先
  // 卡片默认展示英文，cn 模式下批量展开所有中文
  langMode: "en" | "cn";
  setLangMode: (mode: "en" | "cn") => void;
  toggleLangMode: () => void;

  // 知识点难度筛选
  knowledgeLevel: Level | "all";
  setKnowledgeLevel: (level: Level | "all") => void;
}

export const useStore = create<AppState>((set) => ({
  langMode: "en",
  setLangMode: (mode) => set({ langMode: mode }),
  toggleLangMode: () =>
    set((state) => ({
      langMode: state.langMode === "en" ? "cn" : "en",
    })),

  knowledgeLevel: "all",
  setKnowledgeLevel: (level) => set({ knowledgeLevel: level }),
}));
