import { useState, useEffect } from "react";
import { Volume2, ChevronDown, Languages, MessageSquareText } from "lucide-react";
import type { Slang } from "@/types";
import { useStore } from "@/store";
import { cn } from "@/lib/utils";

// 俚语 Tab：英文优先卡片，含发音、用法示例
export default function SlangTab({ slang }: { slang: Slang[] }) {
  return (
    <div className="animate-fade-in">
      <div className="flex items-center gap-2 mb-5">
        <MessageSquareText className="w-5 h-5 text-accent-cyan" />
        <h3 className="font-display text-2xl tracking-wide text-white">
          俚语与口语表达
        </h3>
        <span className="text-xs text-text-muted ml-auto">
          {slang.length} 条 · 含发音与例句
        </span>
      </div>

      <div className="space-y-4">
        {slang.map((s) => (
          <SlangCard key={s.id} slang={s} />
        ))}
      </div>
    </div>
  );
}

function SlangCard({ slang }: { slang: Slang }) {
  const { langMode } = useStore();
  const [expanded, setExpanded] = useState(langMode === "cn");

  useEffect(() => {
    setExpanded(langMode === "cn");
  }, [langMode]);

  return (
    <div className="glass-card p-5 md:p-6">
      {/* 词条头部 */}
      <div className="flex items-start justify-between gap-4 mb-3">
        <div>
          <h3 className="font-display text-2xl md:text-3xl tracking-wide text-white mb-1">
            {slang.term}
          </h3>
          <div className="flex items-center gap-2 text-sm text-text-muted">
            <Volume2 className="w-3.5 h-3.5" />
            <span className="font-mono">{slang.pronunciation}</span>
          </div>
        </div>
      </div>

      {/* 英文释义 */}
      <p className="font-lyric text-base md:text-lg text-text-primary leading-relaxed mb-3">
        {slang.en}
      </p>

      {/* 中文释义（可折叠） */}
      <div
        className={cn(
          "grid transition-all duration-300",
          expanded
            ? "grid-rows-[1fr] opacity-100"
            : "grid-rows-[0fr] opacity-0"
        )}
      >
        <div className="overflow-hidden">
          <div className="pt-3 border-t border-white/[0.06] space-y-3">
            <div className="flex items-start gap-2">
              <Languages className="w-4 h-4 text-accent-pink flex-shrink-0 mt-0.5" />
              <p className="text-sm text-text-secondary leading-relaxed">
                {slang.cn}
              </p>
            </div>
            <div className="rounded-lg bg-accent-cyan/[0.05] border border-accent-cyan/15 p-3">
              <div className="text-[10px] font-mono uppercase tracking-wider text-accent-cyan mb-1">
                Example
              </div>
              <p className="font-lyric text-sm text-text-primary italic mb-1">
                "{slang.example}"
              </p>
              <p className="text-xs text-text-muted">{slang.exampleCn}</p>
            </div>
          </div>
        </div>
      </div>

      <button
        onClick={() => setExpanded(!expanded)}
        className="mt-3 inline-flex items-center gap-1.5 text-xs font-mono text-text-muted hover:text-accent-pink transition-colors"
      >
        <ChevronDown
          className={cn(
            "w-3.5 h-3.5 transition-transform",
            expanded && "rotate-180"
          )}
        />
        {expanded ? "Hide Chinese" : "View Chinese"}
      </button>
    </div>
  );
}
