import { useState } from "react";
import { ChevronDown, Sparkles, BadgeCheck, Star, ThumbsUp } from "lucide-react";
import type { LyricLine as LyricLineType } from "@/types";
import { cn } from "@/lib/utils";

// 难度等级配色
const levelColors = {
  B1: "bg-green-500/15 text-green-400 border-green-500/30",
  B2: "bg-yellow-500/15 text-yellow-400 border-yellow-500/30",
  C1: "bg-red-500/15 text-red-400 border-red-500/30",
};

const typeLabels = {
  vocab: "词汇",
  grammar: "语法",
  expression: "表达",
};

export default function LyricLine({ line }: { line: LyricLineType }) {
  const [showKnowledge, setShowKnowledge] = useState(false);
  const [showNotes, setShowNotes] = useState(false);

  const hasKnowledge = !!line.knowledge;
  const hasNotes = line.userNotes && line.userNotes.length > 0;
  // 高赞采纳的补充（升级到主线位置）
  const adoptedNotes = line.userNotes?.filter((n) => n.adopted) ?? [];
  const otherNotes = line.userNotes?.filter((n) => !n.adopted) ?? [];

  return (
    <div className="group border-b border-white/[0.04] last:border-b-0">
      <div className="py-4 md:py-5">
        {/* 英文原句 */}
        <p
          className={cn(
            "font-lyric text-lg md:text-2xl leading-relaxed transition-colors",
            hasKnowledge
              ? "cursor-pointer text-text-primary hover:text-accent-pink"
              : "text-text-primary"
          )}
          onClick={() => hasKnowledge && setShowKnowledge(!showKnowledge)}
        >
          {line.en}
          {hasKnowledge && (
            <span
              className={cn(
                "inline-flex items-center ml-2 px-1.5 py-0.5 rounded text-[10px] font-mono font-semibold border align-middle transition-opacity",
                levelColors[line.knowledge!.level],
                showKnowledge ? "opacity-100" : "opacity-50 group-hover:opacity-100"
              )}
            >
              {line.knowledge!.level}
            </span>
          )}
        </p>

        {/* 中文翻译 */}
        <p className="text-sm md:text-base text-text-secondary mt-1.5 leading-relaxed">
          {line.cn}
        </p>

        {/* 操作行 */}
        <div className="flex items-center gap-3 mt-2">
          {hasKnowledge && (
            <button
              onClick={() => setShowKnowledge(!showKnowledge)}
              className="inline-flex items-center gap-1 text-[11px] font-mono text-text-muted hover:text-accent-cyan transition-colors"
            >
              <Sparkles className="w-3 h-3" />
              {showKnowledge ? "收起知识点" : "展开知识点"}
            </button>
          )}
          {hasNotes && (
            <button
              onClick={() => setShowNotes(!showNotes)}
              className="inline-flex items-center gap-1 text-[11px] font-mono text-text-muted hover:text-accent-pink transition-colors"
            >
              <Users className="w-3 h-3" />
              {showNotes ? "收起补充" : `查看 ${line.userNotes!.length} 条用户补充`}
            </button>
          )}
        </div>

        {/* 知识点展开 */}
        {hasKnowledge && (
          <div
            className={cn(
              "grid transition-all duration-300",
              showKnowledge
                ? "grid-rows-[1fr] opacity-100 mt-3"
                : "grid-rows-[0fr] opacity-0"
            )}
          >
            <div className="overflow-hidden">
              <div className="rounded-xl bg-accent-cyan/[0.04] border border-accent-cyan/15 p-4">
                <div className="flex items-center gap-2 mb-2">
                  <span
                    className={cn(
                      "badge border",
                      levelColors[line.knowledge!.level]
                    )}
                  >
                    {line.knowledge!.level}
                  </span>
                  <span className="badge bg-accent-cyan/10 text-accent-cyan border border-accent-cyan/20">
                    {typeLabels[line.knowledge!.type]}
                  </span>
                  <span className="text-[10px] font-mono text-text-muted">
                    知识点
                  </span>
                </div>
                <ul className="space-y-1.5">
                  {line.knowledge!.points.map((point, i) => (
                    <li
                      key={i}
                      className="text-sm text-text-secondary leading-relaxed flex items-start gap-2"
                    >
                      <span className="text-accent-cyan mt-1">▸</span>
                      <span>{point}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        )}

        {/* 用户补充展开（三层共建模型展示） */}
        {hasNotes && (
          <div
            className={cn(
              "grid transition-all duration-300",
              showNotes
                ? "grid-rows-[1fr] opacity-100 mt-3"
                : "grid-rows-[0fr] opacity-0"
            )}
          >
            <div className="overflow-hidden">
              <div className="space-y-2.5">
                {/* 高赞采纳：主线位置 + 特殊标识 */}
                {adoptedNotes.map((note) => (
                  <UserNoteCard key={note.id} note={note} adopted />
                ))}
                {/* 普通用户补充 */}
                {otherNotes.map((note) => (
                  <UserNoteCard key={note.id} note={note} />
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function UserNoteCard({
  note,
  adopted,
}: {
  note: {
    user: string;
    avatar: string;
    likes: number;
    content: string;
  };
  adopted?: boolean;
}) {
  return (
    <div
      className={cn(
        "rounded-xl p-3.5 border transition-colors",
        adopted
          ? "bg-accent-gold/[0.06] border-accent-gold/25"
          : "bg-white/[0.02] border-white/[0.06] hover:border-white/15"
      )}
    >
      <div className="flex items-center justify-between mb-1.5">
        <div className="flex items-center gap-2">
          <span className="text-base">{note.avatar}</span>
          <span className="text-xs font-medium text-text-primary">
            {note.user}
          </span>
          {adopted ? (
            <span className="inline-flex items-center gap-1 badge bg-accent-gold/15 text-accent-gold border border-accent-gold/30">
              <Star className="w-3 h-3 fill-accent-gold" />
              官方采纳
            </span>
          ) : (
            <span className="inline-flex items-center gap-1 badge bg-white/5 text-text-muted border border-white/10">
              <BadgeCheck className="w-3 h-3" />
              用户补充
            </span>
          )}
        </div>
        <div className="inline-flex items-center gap-1 text-xs text-text-muted">
          <ThumbsUp className="w-3 h-3" />
          {note.likes}
        </div>
      </div>
      <p className="text-sm text-text-secondary leading-relaxed">
        {note.content}
      </p>
    </div>
  );
}

function Users({ className }: { className?: string }) {
  // 简单的用户图标，避免再 import
  return (
    <svg
      className={className}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2" />
      <circle cx="9" cy="7" r="4" />
      <path d="M22 21v-2a4 4 0 0 0-3-3.87" />
      <path d="M16 3.13a4 4 0 0 1 0 7.75" />
    </svg>
  );
}
